const v = $input.first().json.values || [];
if (v.length < 500) { throw new Error('ABORT: PIPELINE only ' + v.length); }
return [{ json: { rows: v.length } }];

function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const pipe = $('GET tabs').first().json.values || [];
const vr = $input.first().json.valueRanges || [];
const st = (vr[0] || {}).values || [];
const inv = (vr[1] || {}).values || [];
if (!st.length || !inv.length) { throw new Error('ABORT: STARTUPS/INVESTORS read empty'); }

// user 2026-09-15: angels = named individuals only
const ANGELS = ['gautamkapur','mohit','devesh','mandeepsingh','ankit','vivasvan','sayanghosh','gauthamkrishnan','ishansingh','alexalpert','ignacio','jonathansolamon'];
const A = {}; ANGELS.forEach(function (k) { A[k] = 1; });

const sh = (st[0] || []).map(s);
const S = {}; ['startup','stage','revenue','raise_inr_cr','active'].forEach(function (n) { S[n] = sh.indexOf(n); });
const RE = /pre-?\s*revenue|pre-?\s*launch|pre-?\s*monetis|\bmvp\b/i;
const PRE = {}; const preList = [];
for (let r = 1; r < st.length; r++) { const row = st[r] || []; const n = s(row[S.startup]); if (!n) { continue; }
  if (s(row[S.active]).toLowerCase() !== 'yes') { continue; }
  if (RE.test(s(row[S.stage])) || RE.test(s(row[S.revenue]))) { PRE[nz(n)] = 1; preList.push(n); } }

const ih = (inv[0] || []).map(s);
const II = {}; ['investor','email','cheque_inr_cr'].forEach(function (n) { II[n] = ih.indexOf(n); });
const angelRows = [], maybePerson = [];
for (let r = 1; r < inv.length; r++) { const row = inv[r] || []; const n = s(row[II.investor]); if (!n) { continue; }
  if (A[nz(n)]) { angelRows.push([n, s(row[II.email]), s(row[II.cheque_inr_cr])]); continue; }
  // flag anything that looks like a person but is not on the list, so the user can confirm the list is complete
  const words = n.split(/\s+/);
  const corp = /capital|ventures?|fund|partners?|group|angels?|network|llp|ltd|inc|vc\b|investments?|advisors?|office|studio|labs?|accelerator|holdings/i;
  if (words.length <= 2 && !corp.test(n)) { maybePerson.push([n, s(row[II.email])]); } }

const ph = (pipe[0] || []).map(s);
const P = {}; ['deal_id','startup','investor','owner','deal_shared','pause','next_action','next_due'].forEach(function (n) { P[n] = ph.indexOf(n); if (P[n] < 0) { throw new Error('ABORT: PIPELINE missing ' + n); } });
const queued = [], alreadySent = [];
for (let r = 1; r < pipe.length; r++) { const row = pipe[r] || [];
  if (!A[nz(row[P.investor])]) { continue; }
  if (!PRE[nz(row[P.startup])]) { continue; }
  const sent = s(row[P.deal_shared]).toLowerCase() === 'yes';
  const paused = s(row[P.pause]).toLowerCase() === 'yes';
  const rec = [r + 1, s(row[P.deal_id]), s(row[P.startup]), s(row[P.investor]), s(row[P.owner]), s(row[P.next_due])];
  if (sent) { alreadySent.push(rec); } else if (!paused) { queued.push(rec); } }
queued.sort(function (a, b) { return String(a[5]).localeCompare(String(b[5])); });
return [{ json: { pre_revenue_startups: preList, pre_revenue_count: preList.length,
  angels_found: angelRows, angels_found_count: angelRows.length,
  possible_angels_not_on_list: maybePerson,
  queued_angel_prerevenue_deals: queued.length, queued: queued,
  already_sent_angel_prerevenue: alreadySent.length, sent_sample: alreadySent.slice(0, 15),
  earliest_due: queued.length ? queued[0][5] : '(none)' } }];
